import * as THREE from 'three';

// Ashes of the Forgotten — a compact, systems-first dark fantasy RPG.
const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.04;
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x89928d); scene.fog=new THREE.FogExp2(0x89928d,.0105);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,260);
const hemi=new THREE.HemisphereLight(0xb7c2ba,0x35332a,1.05); scene.add(hemi);
const sun=new THREE.DirectionalLight(0xf2d6a4,2.4); sun.position.set(-34,55,22); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-90;sun.shadow.camera.right=90;sun.shadow.camera.top=90;sun.shadow.camera.bottom=-90;sun.shadow.bias=-.0003;scene.add(sun);
const fill=new THREE.DirectionalLight(0x8eabb0,.55);fill.position.set(20,18,-55);scene.add(fill);
const mat=(color,rough=.9,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const materials={earth:mat(0x514f40),path:mat(0x807762),stone:mat(0x77766c),darkstone:mat(0x494c48),wood:mat(0x49382b),plank:mat(0x72583b),roof:mat(0x393832),leaf:mat(0x303d32),leaf2:mat(0x48513c),grass:mat(0x5c6048),gold:mat(0xb49557,.5,.5),steel:mat(0x8c9693,.35,.72),skin:mat(0xb18a6c),cloth:mat(0x51574e),red:mat(0x693a31),black:mat(0x242b2a),bone:mat(0xb7ae94),glow:mat(0xf1b65c,.4,.15)};
function mesh(geo,material,x,y,z,parent=scene){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function box(x,y,z,sx,sy,sz,m,parent=scene){return mesh(new THREE.BoxGeometry(sx,sy,sz),m,x,y,z,parent)}
function cylinder(x,y,z,rt,rb,h,m,parent=scene,segments=8){return mesh(new THREE.CylinderGeometry(rt,rb,h,segments),m,x,y,z,parent)}
function groundPatch(x,z,sx,sz,m){const g=box(x,-.3,z,sx,.5,sz,m);g.receiveShadow=true;return g}
const world= new THREE.Group();scene.add(world);
groundPatch(0,0,220,220,materials.earth);
// Broken old road and its branching tracks
const road=mesh(new THREE.PlaneGeometry(7,118),materials.path,0,-.015,-39);road.rotation.x=-Math.PI/2;road.receiveShadow=true;
for(let i=0;i<38;i++){const x=(Math.random()-.5)*5,z=13-i*3.1;const s=.15+Math.random()*.55;mesh(new THREE.DodecahedronGeometry(s,0),i%4?materials.path:materials.stone,x,.005,z).rotation.y=Math.random()*4;}
// Soft rolling ground rises around the far forest and castle
for(let i=0;i<35;i++){let x=(Math.random()-.5)*150,z=-35-Math.random()*100,s=5+Math.random()*12;const hill=mesh(new THREE.SphereGeometry(1,10,7),materials.earth,x,-1.2,z);hill.scale.set(s*.8,1+Math.random()*2,s*.6);hill.receiveShadow=true;}
// Stream through the woods
const water=mesh(new THREE.PlaneGeometry(3,78),new THREE.MeshStandardMaterial({color:0x303e3e,roughness:.24,metalness:.18,transparent:true,opacity:.88}),15,-.035,-57);water.rotation.x=-Math.PI/2;
for(let i=0;i<13;i++){const r=.65+Math.random()*.85;const rock=mesh(new THREE.DodecahedronGeometry(r,0),materials.stone,13+Math.sin(i*2)*2,.1,-22-i*6);rock.scale.y=.45;}
// Lanterns, grass clumps, bones and mushrooms are visual landmarks.
function makeTree(x,z,scale=1){const g=new THREE.Group();scene.add(g);const trunk=cylinder(0,1.15,0,.24,.34,2.3,materials.wood,g);trunk.rotation.z=(Math.random()-.5)*.12;for(let i=0;i<3;i++){const crown=mesh(new THREE.IcosahedronGeometry(1,1),i===1?materials.leaf2:materials.leaf,0,2.25+i*.62,0,g);crown.scale.set(1.35-i*.18,1.2-i*.1,1.25-i*.18);}g.position.set(x,0,z);g.scale.setScalar(scale);return g;}
for(let i=0;i<125;i++){let z=-20-Math.random()*88,x=(Math.random()-.5)*70;if(Math.abs(x)<8)continue;if(z<-75&&Math.abs(x)<16)continue;makeTree(x,z,.72+Math.random()*.85)}
for(let i=0;i<65;i++){const x=(Math.random()-.5)*95,z=(Math.random()-.5)*110-22;const h=.16+Math.random()*.38;const b=mesh(new THREE.ConeGeometry(.12,h,5),i%3?materials.grass:materials.leaf2,x,h/2,z);b.rotation.z=(Math.random()-.5)*.3;}
// Village: timber, stone and thatch, laid around a common green.
function house(x,z,s=1,angle=0){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);g.rotation.y=angle;box(0,1.45,0,5*s,2.9*s,4*s,materials.wood,g);box(0,1.3,2.04*s,5.1*s,2.6*s,.18*s,materials.plank,g);const roof=mesh(new THREE.ConeGeometry(3.9*s,2.3*s,4),materials.roof,0,3.8*s,0,g);roof.rotation.y=Math.PI/4;roof.scale.set(1,1,.85);box(0,.84,2.14*s,.95*s,1.7*s,.08,materials.darkstone,g);for(const side of [-1,1]){box(side*1.35*s,1.9*s,2.14*s,.64*s,.62*s,.09,materials.glow,g);box(side*1.35*s,1.9*s,2.2*s,.08,.8*s,.08,materials.wood,g);box(side*1.35*s,1.9*s,2.2*s,.8*s,.08,.08,materials.wood,g);}for(let a=-1;a<=1;a+=2){box(a*2.15*s,1.2*s,2.17*s,.13,.18*s,.12,materials.stone,g)}return g;}
house(-10,-5,1,0);house(9,-9,.9,.16);house(-11,-17,.82,-.12);house(11,-20,1,.08);house(-1,-27,.78,Math.PI);
// Well, gallows, fences, market stall, and the bell tower
cylinder(0,.55,-12,1.15,1.35,1.1,materials.stone);cylinder(0,1.2,-12,.14,.14,2.5,materials.wood);cylinder(1.25,1.2,-12,.14,.14,2.5,materials.wood);box(.6,2.4,-12,2.2,.16,.18,materials.wood);const wellWater=cylinder(0,1.08,-12,.86,.86,.07,mat(0x242e2d,.2),scene,16);
for(let i=0;i<2;i++){box(-16+i*4,.7,-3,.12,1.4,10,materials.plank);for(let z=-7;z<3;z+=2)box(-14+i*4,.7,z,4,.09,.09,materials.wood);}
box(15,1,-1,4,2,.22,materials.wood);for(let x=13;x<17;x+=2)box(x,1,0,.12,2,.12,materials.plank);const canopy=mesh(new THREE.ConeGeometry(3.2,1.5,4),materials.red,15,2.55,-1);canopy.rotation.y=Math.PI/4;
// Graveyard cross and bell-frame at the village edge
for(let i=0;i<6;i++){box(-19+i*1.5,.4,-23,.35,.8,.25,materials.stone);box(-19+i*1.5,.88,-23,.65,.1,.25,materials.stone)}
box(18,3,-30,.25,6,.25,materials.wood);box(20,3,-30,.25,6,.25,materials.wood);box(19,5.8,-30,3,.25,.3,materials.wood);const villageBell=cylinder(19,4.7,-30,.55,.72,1.2,materials.gold);villageBell.position.y=4.8;
// Castle walls and keep, visible across the forest ridge.
function tower(x,z,h=12){cylinder(x,h/2,z,2.15,2.5,h,materials.darkstone,scene,8);const cap=mesh(new THREE.ConeGeometry(3.1,2.2,8),materials.roof,x,h+1,z);cap.rotation.y=Math.PI/8;for(let i=0;i<4;i++){const a=i*Math.PI/2;box(x+Math.cos(a)*1.8,h*.68,z+Math.sin(a)*1.8,.18,1.2,.18,materials.stone).rotation.y=-a;}}
box(-8,3,-86,17,6,2,materials.darkstone);box(9,3,-86,17,6,2,materials.darkstone);box(0,3,-96,2,6,20,materials.darkstone);tower(-16,-87,13);tower(16,-87,15);box(0,5,-91,13,10,11,materials.darkstone);const keepRoof=mesh(new THREE.ConeGeometry(10,5,4),materials.roof,0,12.5,-91);keepRoof.rotation.y=Math.PI/4;
// Broken battlements, fallen columns and a crypt entrance
for(let i=0;i<8;i++){const b=box(-9+i*2.5,6.1,-86,1.2,1.2,1.2,materials.stone);if(i%2)b.rotation.z=.18;}
const caveArch=mesh(new THREE.TorusGeometry(2.2,.36,7,12,Math.PI),materials.stone,-22,2,-51);caveArch.rotation.z=Math.PI;box(-22,1,-51,3.8,2,.45,materials.darkstone);
for(let i=0;i<7;i++){const col=cylinder(22+i*1.1,1.2,-57,.32,.38,2.4,materials.stone);col.rotation.z=(Math.random()-.5)*.9;}
// Firelight around the camp and lanterns
function fire(x,z){const f=new THREE.PointLight(0xff9a48,2.2,13,2);f.position.set(x,1.3,z);scene.add(f);const flame=mesh(new THREE.ConeGeometry(.25,.8,6),materials.glow,x,.5,z);return {light:f,flame};}
const campFire=fire(8,-49);fire(-19,-56);for(const [x,z] of [[-13,-9],[14,-12],[2,-31],[19,-30]]){const l=new THREE.PointLight(0xffbd70,1.15,9,2);l.position.set(x,2.3,z);scene.add(l);const o=mesh(new THREE.SphereGeometry(.12,8,6),materials.glow,x,2.3,z);}
// Actor silhouettes are hand-built from low-poly forms; gear is readable at game distance.
function makeActor(kind='human',outfit=materials.cloth){const g=new THREE.Group();const body=mesh(new THREE.CapsuleGeometry(.34,.75,4,7),outfit,0,1.15,0,g);body.scale.set(1,.92,.72);const head=mesh(new THREE.SphereGeometry(.25,10,8),kind==='undead'?materials.bone:materials.skin,0,1.88,0,g);head.scale.y=1.1;const hood=kind==='undead'?null:mesh(new THREE.ConeGeometry(.3,.48,6),kind==='monster'?materials.red:materials.wood,0,2.18,-.02,g);const legs=[];for(const x of [-.17,.17]){const leg=mesh(new THREE.CapsuleGeometry(.12,.48,3,6),kind==='undead'?materials.darkstone:materials.black,x,.42,0,g);legs.push(leg)}const arms=[];for(const x of [-.43,.43]){const arm=mesh(new THREE.CapsuleGeometry(.1,.45,3,6),outfit,x,1.27,0,g);arms.push(arm)}const sword=box(.52,1.02,-.25,.1,.85,.1,materials.steel,g);sword.rotation.x=-.35;sword.rotation.z=-.45;const shield=mesh(new THREE.CylinderGeometry(.42,.42,.12,8),materials.wood,-.52,1,-.12,g);shield.rotation.z=Math.PI/2;const crest=mesh(new THREE.CircleGeometry(.21,6),materials.gold,-.59,1,-.12,g);crest.rotation.y=Math.PI/2;return {group:g,body,head,legs,arms,sword,shield,kind};}
const player=makeActor('human',materials.black);scene.add(player.group);player.group.position.set(0,0,9);player.group.scale.setScalar(1.03);
const npcData=[
 {name:'Maelin Voss',role:'Village keeper · fiercely protective',personality:'A widowed keeper with a soft voice and an iron memory.',x:0,z:-11,color:0x71624a,routine:'well',lines:['The bell beneath the well has rung twice this week. There is no bell down there. I know—I buried my husband above it.'],reputation:0},
 {name:'Sister Ysra',role:'Keeper of the roadside shrine',personality:'A former soldier who trusts deeds, never prayers.',x:-17,z:-10,color:0x777b69,routine:'shrine',lines:['The dead are not wicked for remembering. It is the living who keep changing the story.'],reputation:0},
 {name:'Tomas Reed',role:'Blacksmith · blunt, observant',personality:'A veteran smith who keeps every broken blade he ever made.',x:13,z:-4,color:0x65443a,routine:'forge',lines:['Your sword has a hungry edge. Keep it fed, and it may keep you.'],reputation:0},
 {name:'Bera Holt',role:'Herbalist · curious and kind',personality:'Collects names of plants and people with equal care.',x:16,z:-19,color:0x65724c,routine:'herbs',lines:['Fog carries voices. Not ghosts, exactly—more like the shape a promise leaves behind.'],reputation:0},
 {name:'Captain Orin',role:'Village watch · exacting',personality:'A retired mercenary trying to teach courage without cruelty.',x:-8,z:-29,color:0x59646a,routine:'patrol',lines:['I have seen men call fear cowardice. Usually it is the first honest thing they have felt.'],reputation:0},
 {name:'Nella Pike',role:'Innkeeper · knows every secret',personality:'Laughs loudly so nobody notices when she is listening.',x:-10,z:-5,color:0x7e493a,routine:'inn',lines:['A stranger asked after the castle. Paid in silver, spoke like a man saying goodbye.'],reputation:0},
 {name:'Hobb Fen',role:'Fisher · patient, superstitious',personality:'Will not fish the stream after sunset, and won't say why.',x:12,z:-26,color:0x62716f,routine:'stream',lines:['Caught a child’s shoe in my net. Dry as bone. The stream runs uphill some nights.'],reputation:0},
 {name:'Vey Ansel',role:'Runaway scholar · evasive',personality:'Reads forbidden histories and forgets to eat.',x:-23,z:-49,color:0x5b4b68,routine:'ruins',lines:['The Ash King was not a king. That is the first lie they taught us.'],reputation:0},
 {name:'Dain Marr',role:'Mercenary deserter · ashamed',personality:'Fled the castle guard after seeing what the captain became.',x:8,z:-48,color:0x574d40,routine:'camp',lines:['I can hear them drilling in the courtyard. They have been dead for a century.'],reputation:0},
 {name:'Edda Vale',role:'The bell-tender · missing',personality:'A voice in the crypt, still keeping the village’s time.',x:0,z:-82,color:0x887a61,routine:'castle',lines:['If you have come to silence me, listen first. I have held the door shut from the wrong side.'],reputation:0}
];
const npcs=[];
for(let i=0;i<npcData.length;i++){const d=npcData[i],a=makeActor('human',mat(d.color));a.group.position.set(d.x,0,d.z);a.group.scale.setScalar(.91);scene.add(a.group);npcs.push({...d,...a,type:'npc',home:new THREE.Vector3(d.x,0,d.z),phase:Math.random()*6.28,opinion:0,met:false});}

