const npcs=[];
for(let i=0;i<npcData.length;i++){const d=npcData[i],a=makeActor('human',mat(d.color));a.group.position.set(d.x,0,d.z);a.group.scale.setScalar(.91);scene.add(a.group);npcs.push({...d,...a,type:'npc',home:new THREE.Vector3(d.x,0,d.z),phase:Math.random()*6.28,opinion:0,met:false});}

const enemySpecs={bandit:{label:'Ash-road bandit',hp:58,damage:12,speed:2.25,xp:22,mat:mat(0x594338),color:0xaa6954},undead:{label:'Hollow sentinel',hp:74,damage:16,speed:1.55,xp:32,mat:materials.darkstone,color:0x9ca99b},monster:{label:'Mire hound',hp:48,damage:10,speed:3.0,xp:20,mat:materials.red,color:0xc57955},mercenary:{label:'Castle mercenary',hp:92,damage:19,speed:1.8,xp:40,mat:mat(0x41494b),color:0xb6a16c},boss:{label:'The Bell-Knight',hp:300,damage:24,speed:1.8,xp:180,mat:mat(0x292d2a),color:0xe1ad5f}};
const enemies=[];
function spawnEnemy(type,x,z,boss=false){const spec=enemySpecs[type],a=makeActor(type==='undead'?'undead':type==='monster'?'monster':'human',spec.mat);a.group.position.set(x,0,z);a.group.scale.setScalar(boss?1.65:type==='monster'?.82:1);scene.add(a.group);const e={...a,type:'enemy',enemyType:type,label:spec.label,hp:spec.hp,maxHp:spec.hp,damage:spec.damage,speed:spec.speed,xp:spec.xp,home:new THREE.Vector3(x,0,z),phase:Math.random()*6,alert:false,attack:0,stagger:0,alive:true,boss,phaseIndex:1,hitFlash:0};enemies.push(e);return e;}
spawnEnemy('bandit',6,-43);spawnEnemy('bandit',11,-53);spawnEnemy('monster',-10,-37);spawnEnemy('undead',-20,-61);spawnEnemy('undead',-8,-74);spawnEnemy('mercenary',13,-70);const boss=spawnEnemy('boss',0,-82,true);boss.group.visible=false;
const state={health:100,maxHealth:100,stamina:100,maxStamina:100,xp:0,level:1,tonics:2,gold:12,attack:0,attackKind:'',block:false,dodge:0,invuln:0,dead:false,clock:17.2,weather:'Mist',reputation:0,kills:0,equipped:'Iron Oath',armor:'Wayfarer mail',quests:{main:0,grave:0,scholar:0,deserter:0},inventory:['Iron Oath','Wayfarer mail','Ash tonic ×2','Old village key'],choices:[],selectedTab:'pack',region:'OLD VILLAGE',started:false};
const questText=[['Find Maelin at the village well.','Follow the bell’s echo into the old crypt.','Face the Bell-Knight beneath the castle.','Choose what becomes of Edda and the bell.','The village must live with what you chose.'],['Look for a sign at the old graves.','Return to Sister Ysra with what you found.','The graves are at rest—for now.'],['Find Vey Ansel among the forest ruins.','Decide whether the old history should be shared.','Vey will carry the truth beyond the Marches.'],['Speak with Dain at the abandoned camp.','Help Dain face the patrol he abandoned.','Dain has made his peace.']];
function objective(){const m=state.quests.main;return questText[0][Math.min(m,4)]}
function refreshQuest(){const m=state.quests.main;document.querySelector('#quest-title').textContent=m===0?'The Bell Beneath the Ash':m<4?'The Bell Beneath the Ash':'A Village in the Dark';document.querySelector('#quest-objective').textContent=objective();document.querySelector('#level').textContent=String(state.level).padStart(2,'0');document.querySelector('#tonic-count').textContent=state.tonics;}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2500)}
function setQuest(id,step){if(state.quests[id]>=step)return;state.quests[id]=step;refreshQuest();toast(id==='main'?'QUEST UPDATED · '+objective():'THREAD RESOLVED · '+({grave:'A Mercy for the Dead',scholar:'The Names Beneath',deserter:'A Soldier’s Debt'}[id]||''));}
function gainXP(n){state.xp+=n;if(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.maxHealth+=12;state.health=Math.min(state.maxHealth,state.health+25);state.maxStamina+=8;toast(`RENOWN · LEVEL ${state.level} — vigor restored`)}document.querySelector('#xp-fill').style.width=`${Math.min(100,state.xp/(state.level*100)*100)}%`;document.querySelector('#level').textContent=String(state.level).padStart(2,'0');}
function updateHUD(){document.querySelector('#health-fill').style.width=`${state.health/state.maxHealth*100}%`;document.querySelector('#health-value').textContent=Math.ceil(state.health);document.querySelector('#stamina-fill').style.width=`${state.stamina/state.maxStamina*100}%`;document.querySelector('#tonic-count').textContent=state.tonics;}
function addMemory(text){state.choices.push(text);}
function showDialogue(npc){if(!npc)return;state.interacting=npc;npc.met=true;document.querySelector('#speaker-name').textContent=npc.name;document.querySelector('#speaker-mood').textContent=`${npc.role} · ${npc.opinion>1?'warmer than before':npc.opinion<0?'does not trust you':'measures every word'}`;const text=document.querySelector('#dialogue-text'),opts=document.querySelector('#dialogue-options');opts.innerHTML='';let line=npc.lines[0];
 if(npc.name==='Maelin Voss'&&state.quests.main===0){line='The bell beneath the well has rung twice this week. There is no bell down there. I know—I buried my husband above it. Will you go where I cannot?';option(opts,'I’ll find what is calling.','Accept the main quest',()=>{setQuest('main',1);npc.opinion++;closeModal('dialogue')});option(opts,'Not while the sun still shines.','Leave',()=>closeModal('dialogue'));}
 else if(npc.name==='Maelin Voss'&&state.quests.main>=1&&state.quests.main<4){line=state.quests.main===1?'The road west is older than our graves. Follow it through the black trees. If you hear your name, do not answer.':state.quests.main===2?'You found the source. I can see it in your face. What did it ask of you?':'Whatever you chose, we will endure it. That is what a village does.';option(opts,'Tell me what you know of Edda.','Listen',()=>{npc.opinion++;line='She rang the bell for the dead when the fever came. The lord forbade it. Edda rang it anyway—and the dead answered.';text.textContent=line;opts.innerHTML='';option(opts,'I understand.','Close',()=>closeModal('dialogue'))});option(opts,'I have to go.','Leave',()=>closeModal('dialogue'));}
 else if(npc.name==='Sister Ysra'){if(state.quests.grave===0){line='Three markers have been disturbed. The names were scraped away, not the bones. Search the graves by the bell-frame. Bring me the names—not the remains.';option(opts,'I’ll learn who they were.','Accept · A Mercy for the Dead',()=>{setQuest('grave',1);closeModal('dialogue')})}else if(state.quests.grave===1&&playerHas('grave-token')){line='Alwen, Cor, and little Sella. They were not soldiers. They were the first villagers to die in the fever. Let the names be spoken.';option(opts,'Speak their names and leave the dead at rest.','Show mercy',()=>{removeItem('grave-token');setQuest('grave',2);state.reputation++;npc.opinion+=2;gainXP(55);closeModal('dialogue');toast('SISTER YSRA REMEMBERS YOUR MERCY')});option(opts,'Take the silver from the grave.','Profit',()=>{removeItem('grave-token');setQuest('grave',2);state.gold+=18;state.reputation--;npc.opinion-=2;gainXP(35);addMemory('You took silver from the unnamed dead.');closeModal('dialogue');toast('18 CROWNS · THE DEAD DO NOT FORGET')})}else line=state.quests.grave>=2?'I speak their names each dusk. That is all the justice I can give.':'You have not found the names. The dead have waited this long.';option(opts,'The dead deserve their names.','Leave',()=>closeModal('dialogue'))}
 else if(npc.name==='Vey Ansel'){if(state.quests.scholar===0){line='There is a ledger in the ruined watchtower. It names the people the court erased to make its history tidy. I need it—but the hollow things guard the way.';option(opts,'I’ll find the ledger.','Accept · The Names Beneath',()=>{setQuest('scholar',1);closeModal('dialogue')})}else if(state.quests.scholar===1&&playerHas('ledger')){line='These names could unmake the lord’s claim to the Marches. Or bring soldiers here to bury the proof. Will you help me speak them aloud?';option(opts,'The truth belongs to everyone.','Share the ledger',()=>{removeItem('ledger');setQuest('scholar',2);state.reputation++;npc.opinion+=2;gainXP(65);addMemory('You chose to share the erased names.');closeModal('dialogue');toast('THE NAMES WILL BE READ ALOUD')});option(opts,'Burn it. The village must stay hidden.','Protect the living',()=>{removeItem('ledger');setQuest('scholar',2);state.reputation--;npc.opinion-=1;state.gold+=25;gainXP(60);addMemory('You burned the ledger to protect the village.');closeModal('dialogue');toast('THE TRUTH DIED QUIETLY · 25 CROWNS')})}else line=state.quests.scholar>=2?'History is a wound that will not close. At least now it can breathe.':'The ruined watchtower lies west of the stream.';option(opts,'I’ll remember that.','Leave',()=>closeModal('dialogue'))}
