const pickups=[{name:'grave-token',label:'Three names scratched on bone',x:-14,z:-23,required:()=>state.quests.grave===1},{name:'ledger',label:'The erased names · court ledger',x:-23,z:-49,required:()=>state.quests.scholar===1},{name:'buried coffer',label:'Old crown · 10 crowns',x:22,z:-57,required:()=>true}];
