const keys={};let yaw=0,cameraYaw=0,pitch=.12,mouseDown=false,lastPointer={x:0,y:0},nearTarget=null,nearPickup=null,animTime=0,weatherTimer=0,weatherState=0;
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyI'||e.code==='Escape')toggleInventory();if(e.code==='KeyF')attack(false);if(e.code==='KeyR')attack(true);if(e.code==='KeyQ'){state.block=true}if(e.code==='Digit2')useTonic();if(e.code==='Space')dodge();});
window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyQ')state.block=false});
canvas.addEventListener('pointerdown',e=>{if(e.button===0){canvas.requestPointerLock?.();attack(false)}if(e.button===2){e.preventDefault();state.block=true}});window.addEventListener('pointerup',e=>{if(e.button===2)state.block=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){yaw-=e.movementX*.0026;cameraYaw=yaw;pitch=THREE.MathUtils.clamp(pitch+e.movementY*.0015,-.05,.42)}});
document.querySelector('#begin').onclick=()=>{state.started=true;document.querySelector('#start-screen').classList.add('gone');document.querySelector('#interaction-hint').classList.add('show');toast('THE MARCHES · 17TH DAY OF THE WITHERING');};
document.querySelector('#inventory-button').onclick=toggleInventory;document.querySelector('#menu-button').onclick=toggleInventory;
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('.modal').classList.add('hidden'));
document.querySelector('#respawn').onclick=()=>{state.dead=false;state.health=state.maxHealth;player.group.position.set(0,0,9);yaw=0;document.querySelector('#death-screen').classList.add('hidden');toast('THE ROAD RETURNS YOU')};
