function nearestInteraction(){let best=3.0,found=null;for(const n of npcs){if(n.name==='Edda Vale'&&state.quests.main<3)continue;const d=player.group.position.distanceTo(n.group.position);if(d<best){best=d;found=n}}return found}
// Small quest relics are tangible world objects, not menu-only rewards.
for(const p of pickups){p.mesh=new THREE.Group();scene.add(p.mesh);p.mesh.position.set(p.x,.35,p.z);const crystal=mesh(new THREE.OctahedronGeometry(.25),p.name==='grave-token'?materials.bone:p.name==='ledger'?materials.plank:materials.gold,0,0,0,p.mesh);crystal.rotation.x=.4;const light=new THREE.PointLight(0xc69b54,.45,3);light.position.y=.35;p.mesh.add(light);if(p.name==='buried coffer'){box(p.x,.3,p.z,.8,.55,.55,materials.wood);box(p.x,.58,p.z,.88,.12,.62,materials.gold);p.mesh.visible=false}}
function floatingDamage(target,amount){const el=document.createElement('div');el.className='damage-number';el.textContent=amount;const v=target.group.position.clone();v.y+=2.5;v.project(camera);el.style.left=`${(v.x*.5+.5)*innerWidth}px`;el.style.top=`${(-v.y*.5+.5)*innerHeight}px`;document.querySelector('#damage-number-layer').appendChild(el);setTimeout(()=>el.remove(),850)}
function attack(heavy){if(!state.started||state.dead||state.attack>0||state.stamina<(heavy?28:15))return;state.attack=heavy?.64:.42;state.attackKind=heavy?'heavy':'light';state.stamina-=heavy?28:15;player.sword.rotation.x=-1.25;player.sword.rotation.z=-.8;const pos=player.group.position;const forward=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));let target=null,best=heavy?3.3:2.55;for(const e of enemies){if(!e.alive||!e.group.visible)continue;const v=e.group.position.clone().sub(pos);const dist=v.length();if(dist<best&&forward.dot(v.normalize())>.17){target=e;best=dist}}if(target){const dmg=Math.round((heavy?32:21)*(state.playerDamage||1)*(state.level>1?1+(state.level-1)*.06:1));target.hp-=dmg;target.alert=true;target.stagger=heavy?.7:.32;target.hitFlash=.15;floatingDamage(target,dmg);if(target.boss){const ratio=target.hp/target.maxHp;if(ratio<.65&&target.phaseIndex===1){target.phaseIndex=2;target.speed=2.3;target.damage=30;toast('BELL-KNIGHT · THE SECOND TOLL');}if(ratio<.3&&target.phaseIndex===2){target.phaseIndex=3;target.speed=2.75;target.damage=35;toast('BELL-KNIGHT · NO MORE MERCY');}}if(target.hp<=0)killEnemy(target)}
 for(const n of npcs){if(n.group.position.distanceTo(pos)<2.2&&n!==nearTarget){n.opinion-=1;state.reputation--;toast(`${n.name.toUpperCase()} WILL REMEMBER THIS`);break}}}
function killEnemy(e){if(!e.alive)return;e.alive=false;e.group.visible=false;state.kills++;gainXP(e.xp);state.gold+=e.boss?30:2+Math.floor(Math.random()*4);toast(`${e.label.toUpperCase()} · ${e.xp} RENOWN`);if(e.boss){setQuest('main',3);boss.group.visible=false;const edda=npcs.find(n=>n.name==='Edda Vale');edda.group.visible=true;edda.group.position.set(0,0,-80);toast('THE BELL-KNIGHT FALLS · THE DOOR IS OPEN');}if(state.quests.deserter===1&&state.kills>=3)document.querySelector('#quest-objective').textContent='Return to Dain at the abandoned camp.'}
function hurtPlayer(damage,attacker){if(state.invuln>0||state.dead)return;let amount=damage;if(state.block){const parry=state.blockTime<.32;if(parry){amount=0;attacker.stagger=1.05;attacker.attack=0;toast('PARRY · THE MOMENT IS YOURS')}else amount=Math.ceil(damage*.23);state.stamina=Math.max(0,state.stamina-(parry?7:13));}state.health-=amount;state.invuln=.45;document.querySelector('#combat-flash').classList.remove('active');void document.querySelector('#combat-flash').offsetWidth;document.querySelector('#combat-flash').classList.add('active');if(amount>0){floatingDamage(player,amount);toast('STRUCK · HOLD Q TO GUARD OR DODGE')}if(state.health<=0){state.health=0;state.dead=true;document.querySelector('#death-screen').classList.remove('hidden')}updateHUD()}
function updateEnemies(dt){const p=player.group.position;for(const e of enemies){if(!e.alive||!e.group.visible)continue;e.attack=Math.max(0,e.attack-dt);e.stagger=Math.max(0,e.stagger-dt);e.hitFlash=Math.max(0,e.hitFlash-dt);const d=e.group.position.distanceTo(p);if(d<(e.boss?19:11))e.alert=true;if(e.stagger>0)continue;if(e.alert&&d<25){const dir=p.clone().sub(e.group.position);dir.y=0;const len=dir.length();dir.normalize();e.group.rotation.y=Math.atan2(-dir.x,-dir.z);if(len>(e.boss?2.45:1.75)){e.group.position.addScaledVector(dir,e.speed*dt);}
 else if(e.attack<=0){e.attack=e.boss?.95:1.25;if(Math.random()<.8){e.group.userData.swing=.42;setTimeout(()=>{if(e.alive&&e.group.visible&&e.group.position.distanceTo(player.group.position)<(e.boss?3.4:2.3))hurtPlayer(e.damage,e)},330)}}}else{e.phase+=dt*.8;e.group.position.x=e.home.x+Math.sin(e.phase)*1.3;e.group.position.z=e.home.z+Math.cos(e.phase*.7)*1.4;e.group.rotation.y=Math.sin(e.phase)*.45;}}
}
function updateNPCs(dt){const hour=state.clock%24;for(const n of npcs){if(!n.group.visible)continue;let target=n.home.clone();if(n.routine==='patrol'){target.x+=Math.sin(state.clock*.24+n.phase)*5;target.z+=Math.cos(state.clock*.24+n.phase)*4}if(n.routine==='well')target.x+=Math.sin(state.clock*.18+n.phase)*1.8;if(n.routine==='shrine')target.x+=hour>19?2:Math.sin(state.clock*.2+n.phase)*1.4;if(n.routine==='forge')target.z+=Math.sin(state.clock*.3+n.phase)*1.3;if(n.routine==='herbs'){target.x+=Math.sin(state.clock*.18+n.phase)*2;target.z+=Math.cos(state.clock*.18+n.phase)*2}if(n.routine==='inn'&&hour>21)target.x=-8;if(n.routine==='stream'){target.x+=Math.sin(state.clock*.1+n.phase)*2;target.z+=Math.cos(state.clock*.1+n.phase)*2}if(n.routine==='ruins')target.x+=Math.sin(state.clock*.16+n.phase)*1.5;if(n.routine==='camp')target.x+=Math.cos(state.clock*.23+n.phase)*1.8;
 let threat=false;for(const e of enemies)if(e.alive&&e.alert&&n.group.position.distanceTo(e.group.position)<8){threat=true;const away=n.group.position.clone().sub(e.group.position).normalize();target.copy(n.group.position).addScaledVector(away,12);n.opinion-=.002;break}if(hour>23||hour<5){target.copy(n.home);target.x+=3.5;}
 const v=target.clone().sub(n.group.position);v.y=0;if(v.length()>.3){const step=Math.min(v.length(),(threat?3.1:.7)*dt);n.group.position.addScaledVector(v.normalize(),step);n.group.rotation.y=Math.atan2(-v.x,-v.z);n.legs[0].rotation.x=Math.sin(animTime*7+n.phase)*.28;n.legs[1].rotation.x=-n.legs[0].rotation.x}else{n.legs[0].rotation.x=n.legs[1].rotation.x=0;}}
}

